def adjust_for_splits(sector_prices, sector_metadata, all_dates):
    """Adjust prices for corporate actions (splits, dividends)."""
    adjusted_prices = {}

    for ticker, meta in sector_metadata.items():
        split_history = meta.get('split_history', '')
        if not split_history:
            continue

        # Parse split history to find split dates
        split_date = None
        ratio = 1.0
        for part in split_history.split():
            if 'effective' in part.lower():
                split_str = part.split('effective')[1].strip()
                split_date = parse_date(split_str)
                # Assume 2:1 split
                ratio = 2.0

        if split_date is None or split_date not in all_dates:
            continue

        # Get prices before split
        pre_split_date = None
        pre_split_price = None

        for date_str in sorted(all_dates):
            if date_str <= split_date.strftime('%Y-%m-%d'):
                pre_split_date = date_str
                if ticker in sector_prices.get(pre_split_date, {}):
                    pre_split_price = sector_prices[pre_split_date][ticker]['close']
                else:
                    # Look for any price in range
                    for date_str2, pricemap in sector_prices.items():
                        if date_str2 == pre_split_date and ticker in pricemap:
                            pre_split_price = pricemap[ticker]['close']
                    break

        # Get post-split price
        post_split_date = None
        post_split_price = None

        for date_str in sorted(all_dates):
            if date_str >= split_date.strftime('%Y-%m-%d'):
                post_split_date = date_str
                if ticker in sector_prices.get(post_split_date, {}):
                    post_split_price = sector_prices[post_split_date][ticker]['close']
                else:
                    # Look for any price in range
                    for date_str2, pricemap in sector_prices.items():
                        if date_str2 == post_split_date and ticker in pricemap:
                            post_split_price = pricemap[ticker]['close']
                    break

        if pre_split_price is not None and post_split_price is not None:
            actual_ratio = post_split_price / pre_split_price
            if actual_ratio != 1.0:
                print(f"  {ticker}: Split detected. Pre-split: ${pre_split_price:.2f}, Post-split: ${post_split_price:.2f}")

                # Apply ratio to all post-split dates
                for date_str in all_dates:
                    if date_str >= split_date.strftime('%Y-%m-%d'):
                        if ticker in sector_prices.get(date_str, {}):
                            # Adjust price
                            sector_prices[date_str][ticker]['close'] = sector_prices[date_str][ticker]['close'] * actual_ratio
                            sector_prices[date_str][ticker]['open'] = sector_prices[date_str][ticker]['open'] * actual_ratio
                            sector_prices[date_str][ticker]['high'] = sector_prices[date_str][ticker]['high'] * actual_ratio
                            sector_prices[date_str][ticker]['low'] = sector_prices[date_str][ticker]['low'] * actual_ratio

