def calculate_momentum_score(prices_by_date, ticker, current_date, params):
    """Calculate momentum score for a ticker at a given date.

    Score = price[current_date - skip - lookback] / price[current_date - skip] - 1
    """
    lookback_weeks = params['lookback_weeks']
    skip_recent_weeks = params['skip_recent_weeks']

    # Get all prices for this ticker
    ticker_dates = sorted([(d, p['close']) for d, p in prices_by_date.items() if p['ticker'] == ticker and p['close'] is not None])

    if len(ticker_dates) < 2:
        return None

    current_week = current_date.isocalendar()[1]
    target_week = current_week - skip_recent_weeks

    # Find the week index in our ticker_dates
    if current_week <= len(ticker_dates) and target_week >= 0:
        price_current = ticker_dates[current_week][1]
        price_target = ticker_dates[target_week][1]
    else:
        return None

    # Calculate score
    score = (price_target / price_current) - 1

    # Round to 4 decimal places
    score = round(score, 4)

    return score

def calculate_all_momentum_scores(prices_by_date, all_dates, params):
    """Calculate momentum scores for all dates and sectors."""
    scores_by_date = {}
    ticker_list = ['XLK', 'XLF', 'XLE', 'XLV', 'XLI', 'XLY']

    for date_str in all_dates:
        current_date = parse_date(date_str)
        scores_by_date[date_str] = {}

        for ticker in ticker_list:
            if ticker in prices_by_date.get(date_str, {}):
                score = calculate_momentum_score(prices_by_date, ticker, current_date, params)
                scores_by_date[date_str][ticker] = score
            else:
                scores_by_date[date_str][ticker] = None

    return scores_by_date

# =============================================================================
# Portfolio Selection
# =============================================================================

def select_sectors_by_momentum(scores_by_date, current_date, params):
    """Select top N sectors by momentum score at current date."""
    skip_recent_weeks = params['skip_recent_weeks']
    lookback_weeks = params['momentum']['lookback_weeks']
    top_n = params['portfolio']['top_n']

    current_week = current_date.isocalendar()[1]

    # Get 4-week momentum for risk control
    four_week_scores = {}
    for ticker in ['XLK', 'XLF', 'XLE', 'XLV', 'XLI', 'XLY']:
        if scores_by_date.get(current_date, {}).get(ticker) is not None:
            four_week_scores[ticker] = calculate_momentum_score(prices_by_date, ticker, current_date, params)

    # Get current momentum scores
    current_scores = scores_by_date.get(current_date, {})

    # Filter to valid sectors (non-None scores)
    valid_sectors = [(ticker, score) for ticker, score in current_scores.items() if score is not None]

    # Sort by momentum score descending
    valid_sectors.sort(key=lambda x: x[1], reverse=True)

    # Apply risk control: exclude sectors with negative 4-week momentum
    selected = []
    for ticker, score in valid_sectors:
        four_week_score = four_week_scores.get(ticker, None)
        # Only select if 4-week momentum is non-negative
        if four_week_score is None or four_week_score >= 0:
            selected.append(ticker)
            if len(selected) >= top_n:
                break

    return selected[:top_n]

