def calculate_transaction_costs(new_holdings, prev_holdings, transaction_costs_config):
    """Calculate transaction costs for rebalancing."""
    commission = transaction_costs_config['commission_per_trade']
    spread_bps = transaction_costs_config['spread_bps']

    old_tickers = set(prev_holdings.keys()) if prev_holdings else set()
    new_tickers = set(new_holdings.keys()) if new_holdings else set()

    # Count trades: sell old positions, buy new positions
    sold_tickers = old_tickers - new_tickers
    bought_tickers = new_tickers - old_tickers
    held_tickers = old_tickers & new_tickers

    num_trades = len(sold_tickers) + len(bought_tickers)

    if num_trades == 0:
        return 0.0

    # Calculate spread cost (in basis points of trade value)
    # For simplicity, assume total trade value is proportional to number of positions
    total_commission = num_trades * commission

    # Spread cost - assume average spread
    total_spread_bps = sum(spread_bps.values()) / len(spread_bps)
    spread_cost = (total_spread_bps / 10000.0) * num_trades

    total_cost = total_commission + spread_cost

    return total_cost
